SELECT T2.LAPS, T1.NAME, T1.YEAR, T3.LOCATION FROM RACES AS T1 INNER JOIN RESULTS AS T2 ON T1.RACEID = T2.RACEID INNER JOIN CIRCUITS AS T3 ON T1.CIRCUITID = T3.CIRCUITID ORDER BY T2.LAPS DESC LIMIT 1;
-- ----------sql2------------
-- 0, 2147483648, -1, 2147483648
SELECT T3.LAP, T2.NAME, T2.YEAR, T1.LOCATION FROM CIRCUITS AS T1 INNER JOIN RACES AS T2 ON T1.CIRCUITID = T2.CIRCUITID INNER JOIN LAPTIMES AS T3 ON T3.RACEID = T2.RACEID ORDER BY T3.LAP DESC LIMIT 1;

